-- ---------------------------------------------------------------------------
-- Checks
-- ---------------------------------------------------------------------------

-- 1. The new tables. Expected: 3 rows, ROW_COUNT 0, COLUMNS_:
--      ILR_DUMMY_GUIDE 4, ILR_DUMMY_LEARNER 16, ILR_DUMMY_LEARNING_DELIVERY 17
SELECT TABLE_NAME, ROW_COUNT,
  (SELECT COUNT(*) FROM CAPTURE_DB.INFORMATION_SCHEMA.COLUMNS c WHERE c.TABLE_SCHEMA = t.TABLE_SCHEMA AND c.TABLE_NAME = t.TABLE_NAME) AS COLUMNS_
FROM CAPTURE_DB.INFORMATION_SCHEMA.TABLES t WHERE TABLE_SCHEMA = 'TEST_BASELINE' AND TABLE_NAME LIKE 'ILR_DUMMY_%'
ORDER BY 1;

-- 2. Who has rights on them. Expected: 2 rows, each on 3 tables:
--    INSERT DATA_LOAD_ROLE, SELECT DATA_LOAD_ROLE.
SELECT PRIVILEGE_TYPE, GRANTEE, COUNT(*) AS TABLES_
FROM CAPTURE_DB.INFORMATION_SCHEMA.TABLE_PRIVILEGES
WHERE TABLE_SCHEMA = 'TEST_BASELINE' AND TABLE_NAME LIKE 'ILR_DUMMY_%' AND GRANTEE <> 'ACCOUNTADMIN'
GROUP BY 1, 2 ORDER BY 1, 2;

-- 3. A sample of the table tags. Expected: 6 rows, as listed (every table is
--    checked afterwards by npm run check:tags -- --bronze):
--      LARS_STANDARD: lars, ogl-3, by-hand, public
--      ONSPD: onspd, ogl-3, by-hand, public
--      PUBLISHED_CELL: dwp-restart-scheme,dwp-work-and-health,fuel-poverty-sub-regional,ofgem-price-cap,ons-online-job-adverts,ons-vacs02,onspd-lookups,skills-england-jobs-skills,skills-england-lsip,soc-coding-index, ogl-3, weekly, public
--      CH_COMPANY_PROFILE: companies-house, ogl-3, daily, public
--      GIAS_ESTABLISHMENT: gias, ogl-3, by-hand, public
--      ILR_DUMMY_LEARNER: test-ilr-dummy, test-data, by-hand, internal
SELECT 'SHARED_DB.RAW.LARS_STANDARD' AS TABLE_, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.LAYER', 'SHARED_DB.RAW.LARS_STANDARD', 'table') AS LAYER, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.SOURCE', 'SHARED_DB.RAW.LARS_STANDARD', 'table') AS SOURCE, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.LICENCE', 'SHARED_DB.RAW.LARS_STANDARD', 'table') AS LICENCE, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.REFRESH', 'SHARED_DB.RAW.LARS_STANDARD', 'table') AS REFRESH, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.SENSITIVITY', 'SHARED_DB.RAW.LARS_STANDARD', 'table') AS SENSITIVITY
UNION ALL SELECT 'SHARED_DB.RAW.ONSPD' AS TABLE_, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.LAYER', 'SHARED_DB.RAW.ONSPD', 'table') AS LAYER, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.SOURCE', 'SHARED_DB.RAW.ONSPD', 'table') AS SOURCE, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.LICENCE', 'SHARED_DB.RAW.ONSPD', 'table') AS LICENCE, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.REFRESH', 'SHARED_DB.RAW.ONSPD', 'table') AS REFRESH, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.SENSITIVITY', 'SHARED_DB.RAW.ONSPD', 'table') AS SENSITIVITY
UNION ALL SELECT 'SHARED_DB.RAW.PUBLISHED_CELL' AS TABLE_, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.LAYER', 'SHARED_DB.RAW.PUBLISHED_CELL', 'table') AS LAYER, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.SOURCE', 'SHARED_DB.RAW.PUBLISHED_CELL', 'table') AS SOURCE, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.LICENCE', 'SHARED_DB.RAW.PUBLISHED_CELL', 'table') AS LICENCE, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.REFRESH', 'SHARED_DB.RAW.PUBLISHED_CELL', 'table') AS REFRESH, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.SENSITIVITY', 'SHARED_DB.RAW.PUBLISHED_CELL', 'table') AS SENSITIVITY
UNION ALL SELECT 'SHARED_DB.RAW.CH_COMPANY_PROFILE' AS TABLE_, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.LAYER', 'SHARED_DB.RAW.CH_COMPANY_PROFILE', 'table') AS LAYER, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.SOURCE', 'SHARED_DB.RAW.CH_COMPANY_PROFILE', 'table') AS SOURCE, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.LICENCE', 'SHARED_DB.RAW.CH_COMPANY_PROFILE', 'table') AS LICENCE, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.REFRESH', 'SHARED_DB.RAW.CH_COMPANY_PROFILE', 'table') AS REFRESH, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.SENSITIVITY', 'SHARED_DB.RAW.CH_COMPANY_PROFILE', 'table') AS SENSITIVITY
UNION ALL SELECT 'OPTIONS_DB.RAW.GIAS_ESTABLISHMENT' AS TABLE_, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.LAYER', 'OPTIONS_DB.RAW.GIAS_ESTABLISHMENT', 'table') AS LAYER, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.SOURCE', 'OPTIONS_DB.RAW.GIAS_ESTABLISHMENT', 'table') AS SOURCE, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.LICENCE', 'OPTIONS_DB.RAW.GIAS_ESTABLISHMENT', 'table') AS LICENCE, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.REFRESH', 'OPTIONS_DB.RAW.GIAS_ESTABLISHMENT', 'table') AS REFRESH, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.SENSITIVITY', 'OPTIONS_DB.RAW.GIAS_ESTABLISHMENT', 'table') AS SENSITIVITY
UNION ALL SELECT 'CAPTURE_DB.TEST_BASELINE.ILR_DUMMY_LEARNER' AS TABLE_, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.LAYER', 'CAPTURE_DB.TEST_BASELINE.ILR_DUMMY_LEARNER', 'table') AS LAYER, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.SOURCE', 'CAPTURE_DB.TEST_BASELINE.ILR_DUMMY_LEARNER', 'table') AS SOURCE, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.LICENCE', 'CAPTURE_DB.TEST_BASELINE.ILR_DUMMY_LEARNER', 'table') AS LICENCE, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.REFRESH', 'CAPTURE_DB.TEST_BASELINE.ILR_DUMMY_LEARNER', 'table') AS REFRESH, SYSTEM$GET_TAG('SHARED_DB.GOVERNANCE.SENSITIVITY', 'CAPTURE_DB.TEST_BASELINE.ILR_DUMMY_LEARNER', 'table') AS SENSITIVITY;

-- 4. The dummy learners' column tags. Expected: 13 rows: Ethnicity and
--    LLDDHealthProb special-category, the other 11 personal.
SELECT COLUMN_NAME, TAG_VALUE, LEVEL
FROM TABLE(CAPTURE_DB.INFORMATION_SCHEMA.TAG_REFERENCES_ALL_COLUMNS('CAPTURE_DB.TEST_BASELINE.ILR_DUMMY_LEARNER', 'table'))
WHERE TAG_NAME = 'SENSITIVITY' AND LEVEL = 'COLUMN'
ORDER BY 2, 1;
